create or replace function public.notify_order_status_change() returns trigger language plpgsql security definer set search_path=public as $$ declare v_title text; v_body text; v_type text; begin if new.status=old.status then return new; end if; case new.status when 'funded' then v_type:='order_funded'; v_title:='Payment secured'; v_body:='The buyer has secured the FAV for your order.'; when 'in_progress' then v_type:='order_started'; v_title:='Order started'; v_body:='The seller has started working on your order.'; when 'delivered' then v_type:='order_delivered'; v_title:='Order delivered'; v_body:='Your order has been delivered. Review it and complete the order.'; when 'completed' then v_type:='order_completed'; v_title:='Order completed'; v_body:='The order is complete and the seller has been paid.'; when 'disputed' then v_type:='order_disputed'; v_title:='Order needs attention'; v_body:='A dispute was opened for this order.'; when 'cancelled' then v_type:='order_cancelled'; v_title:='Order cancelled'; v_body:='This order has been cancelled.'; else return new; end case; perform public.notify_user(new.buyer_id,v_type,v_title,v_body,jsonb_build_object('order_id',new.id,'status',new.status)); if new.seller_id<>new.buyer_id then perform public.notify_user(new.seller_id,v_type,v_title,v_body,jsonb_build_object('order_id',new.id,'status',new.status)); end if; return new; end; $$;
revoke all on function public.notify_order_status_change() from public,anon,authenticated;
drop trigger if exists trg_order_status_notifications on public.orders;
create trigger trg_order_status_notifications after update of status on public.orders for each row execute function public.notify_order_status_change();
create or replace function public.notify_order_created() returns trigger language plpgsql security definer set search_path=public as $$ begin perform public.notify_user(new.seller_id,'order_created','New order','A buyer placed an order for your service.',jsonb_build_object('order_id',new.id,'deal_id',new.deal_id)); return new; end; $$;
revoke all on function public.notify_order_created() from public,anon,authenticated;
drop trigger if exists trg_order_created_notification on public.orders;
create trigger trg_order_created_notification after insert on public.orders for each row execute function public.notify_order_created();
